// Package sqlite is the labsession module's Repo on the platform database (queries.sql, generated by sqlc).
package sqlite

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"time"

	"github.com/IhebBelhadj/opsforge-academy/academy/internal/labsession"
	"github.com/IhebBelhadj/opsforge-academy/academy/internal/platform/sqlite"
)

// Repo implements labsession.Repo.
type Repo struct {
	db *sql.DB
	q  *Queries
}

var _ labsession.Repo = (*Repo)(nil)

// NewRepo uses the open database db.
func NewRepo(db *sql.DB) *Repo { return &Repo{db: db, q: New(db)} }

// Create stores a new attempt; labsession.ErrAnotherLabRunning when the user has an active one (unique index).
func (r *Repo) Create(ctx context.Context, a labsession.Attempt) (int64, error) {
	id, err := r.q.InsertAttempt(ctx, InsertAttemptParams{UserID: a.UserID, LabID: a.Lab, CourseID: text(a.Course),
		ItemID: text(a.Item), ContentHash: a.Hash, Status: string(a.Status), StartedAt: sqlite.FormatTime(a.StartedAt)})
	if sqlite.IsUniqueViolation(err) {
		return 0, labsession.ErrAnotherLabRunning
	}
	return id, err
}

// SetPlaces records the attempt's namespace and workspace.
func (r *Repo) SetPlaces(ctx context.Context, id int64, namespace, workspace string) error {
	return r.q.SetPlaces(ctx, SetPlacesParams{Namespace: text(namespace), Workspace: text(workspace), ID: id})
}

// Attempt reads an attempt, or labsession.ErrAttemptNotFound.
func (r *Repo) Attempt(ctx context.Context, id int64) (labsession.Attempt, error) {
	row, err := r.q.GetAttempt(ctx, id)
	if errors.Is(err, sql.ErrNoRows) {
		return labsession.Attempt{}, labsession.ErrAttemptNotFound
	}
	if err != nil {
		return labsession.Attempt{}, err
	}
	return attempt(row)
}

// Active is the user's attempt in setup or running, if any.
func (r *Repo) Active(ctx context.Context, user int64) (labsession.Attempt, bool, error) {
	row, err := r.q.ActiveAttempt(ctx, user)
	if errors.Is(err, sql.ErrNoRows) {
		return labsession.Attempt{}, false, nil
	}
	if err != nil {
		return labsession.Attempt{}, false, err
	}
	a, err := attempt(row)
	return a, err == nil, err
}

// Finish records an attempt's status, end, time, XP and error.
func (r *Repo) Finish(ctx context.Context, a labsession.Attempt) error {
	p := FinishAttemptParams{Status: string(a.Status), Error: text(a.Error), ID: a.ID}
	if a.FinishedAt != nil {
		p.FinishedAt = text(sqlite.FormatTime(*a.FinishedAt))
	}
	if a.Status == labsession.Passed {
		p.Seconds = sql.NullInt64{Int64: int64(a.Seconds), Valid: true}
		p.Xp = sql.NullInt64{Int64: int64(a.XP), Valid: true}
	}
	return r.q.FinishAttempt(ctx, p)
}

// PassedSteps are the attempt's passed steps since its last reset.
func (r *Repo) PassedSteps(ctx context.Context, id int64) (map[string]bool, error) {
	steps, err := r.q.PassedSteps(ctx, id)
	if err != nil {
		return nil, err
	}
	out := make(map[string]bool, len(steps))
	for _, s := range steps {
		out[s] = true
	}
	return out, nil
}

// RecordStep stores a check's result.
func (r *Repo) RecordStep(ctx context.Context, id int64, step string, passed bool, detail json.RawMessage, at time.Time) error {
	p := InsertStepResultParams{AttemptID: id, StepID: step, Detail: string(detail), At: sqlite.FormatTime(at)}
	if passed {
		p.Passed = 1
	}
	return r.q.InsertStepResult(ctx, p)
}

// ClearSteps forgets the attempt's step results.
func (r *Repo) ClearSteps(ctx context.Context, id int64) error { return r.q.ClearSteps(ctx, id) }

// Hints are how many hints of each step the attempt has shown.
func (r *Repo) Hints(ctx context.Context, id int64) (map[string]int, error) {
	rows, err := r.q.HintCounts(ctx, id)
	if err != nil {
		return nil, err
	}
	out := make(map[string]int, len(rows))
	for _, row := range rows {
		out[row.StepID] = int(row.Shown)
	}
	return out, nil
}

// ShowHint records hint idx of a step as shown and counts it, once, in one transaction.
func (r *Repo) ShowHint(ctx context.Context, id int64, step string, idx int, at time.Time) error {
	tx, err := r.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }() // a no-op after Commit
	q := r.q.WithTx(tx)
	n, err := q.InsertHint(ctx, InsertHintParams{AttemptID: id, StepID: step, Idx: int64(idx), At: sqlite.FormatTime(at)})
	if err != nil {
		return err
	}
	if n == 1 {
		if err := q.CountHint(ctx, id); err != nil {
			return err
		}
	}
	return tx.Commit()
}

// Passed are the user's passed attempts, oldest first.
func (r *Repo) Passed(ctx context.Context, user int64) ([]labsession.Attempt, error) {
	rows, err := r.q.PassedAttempts(ctx, user)
	if err != nil {
		return nil, err
	}
	out := make([]labsession.Attempt, len(rows))
	for i, row := range rows {
		if out[i], err = attempt(row); err != nil {
			return nil, err
		}
	}
	return out, nil
}

// Recover moves attempts left in setup to running.
func (r *Repo) Recover(ctx context.Context) (int64, error) { return r.q.RecoverSetups(ctx) }

func attempt(row Attempt) (labsession.Attempt, error) {
	a := labsession.Attempt{ID: row.ID, UserID: row.UserID, Lab: row.LabID, Course: row.CourseID.String,
		Item: row.ItemID.String, Hash: row.ContentHash, Namespace: row.Namespace.String,
		Workspace: row.Workspace.String, Status: labsession.Status(row.Status), HintsUsed: int(row.HintsUsed),
		Seconds: int(row.Seconds.Int64), XP: int(row.Xp.Int64), Error: row.Error.String}
	var err error
	if a.StartedAt, err = sqlite.ParseTime(row.StartedAt); err != nil {
		return a, err
	}
	if row.FinishedAt.Valid {
		t, err := sqlite.ParseTime(row.FinishedAt.String)
		if err != nil {
			return a, err
		}
		a.FinishedAt = &t
	}
	return a, nil
}

func text(s string) sql.NullString { return sql.NullString{String: s, Valid: s != ""} }
